from difflib import SequenceMatcher

def best_match(df, query):
    names = df['FILINGMANAGER_NAME'].astype(str).fillna('')
    q = query.lower()
    best = None
    for i, name in names.items():
        s = name.lower()
        score = SequenceMatcher(None, q, s).ratio()
        if best is None or score > best[0]:
            best = (score, i, name)
    return best

