    for query in ['renaissance technologies', 'berkshire hathaway']:
        score, idx, name = best_match(cp, query)
        acc = cp.loc[idx, 'ACCESSION_NUMBER']
        print(q, query, '->', name, 'score', round(score,3), 'acc', acc)
